logger = get_logger(__name__)

DEFAULT_RESULTS_DIR = Path("bees_algorithm/results")
DEFAULT_BERLIN52_PATH = Path("bees_algorithm/data/berlin52.tsp")


def _load_history_csv(history_path: Path) -> tuple[np.ndarray, np.ndarray]:
    """
    Load an evaluations x seeds history CSV.
    Returns (evaluations, matrix_of_shape_(n_evals, n_seeds)).
    """
    evaluations: list[int] = []
    series: list[list[float]] = []

    with history_path.open("r", newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        header = next(reader)
        n_seeds = len(header) - 1
        series = [[] for _ in range(n_seeds)]
        for row in reader:
            if not row:
                continue
            evaluations.append(int(row[0]))
            for idx in range(n_seeds):
                val = row[idx + 1]
                series[idx].append(float(val) if val != "" else np.nan)

    eval_arr = np.asarray(evaluations, dtype=int)
    mat = np.asarray(series, dtype=float).T  # shape: (n_evals, n_seeds)
    return eval_arr, mat


def plot_tsp_convergence(
    instance: str,
    optimum: int | float | None = None,
    results_dir: str | Path = DEFAULT_RESULTS_DIR,
) -> Path | None:
    """
    Plot evaluations vs. mean best-so-far tour length across runs for SWAP and REVERSE,
    marking the known TSPLIB optimum.
    """
    base = Path(results_dir) / "part_a_tsp"
    hist_dir = base / "histories"
    if optimum is None:
        optimum = TSP_OPTIMA.get(instance)

    candidates = [("SWAP", "#1f77b4"), ("REVERSE", "#d62728")]
    loaded: list[tuple[str, str, np.ndarray, np.ndarray]] = []
    for neigh, color in candidates:
        path = hist_dir / f"{instance}_{neigh}.csv"
        if not path.exists():
            matches = [
                p
                for p in hist_dir.glob(f"{instance}_*.csv")
                if p.stem.lower() == f"{instance}_{neigh}".lower()
            ]
            path = matches[0] if matches else path
        if path.exists():
            evals, mat = _load_history_csv(path)
            loaded.append((neigh, color, evals, mat))

    if not loaded:
        logger.warning(f"No convergence histories found for TSP instance '{instance}'.")
        return None

    fig, ax = plt.subplots(figsize=(8.5, 5.2))
    n_runs = loaded[0][3].shape[1]

    for neigh, color, evals, mat in loaded:
        mean_curve = np.nanmean(mat, axis=1)
        std_curve = np.nanstd(mat, axis=1, ddof=1) if mat.shape[1] > 1 else None
        ax.plot(evals, mean_curve, label=f"{neigh} (mean)", color=color, linewidth=2.0)
        if std_curve is not None:
            ax.fill_between(
                evals,
                mean_curve - std_curve,
                mean_curve + std_curve,
                color=color,
                alpha=0.14,
                label=f"{neigh} (±1 std)",
            )

    if optimum is not None:
        ax.axhline(
            optimum,
            color="black",
            linestyle="--",
            linewidth=1.5,
            label=f"Optimal tour length ($L^*$ = {optimum:,})",
        )

    ax.set_title(
        f"{instance}: Mean Best-So-Far Convergence ({n_runs} Runs, 30,000 Evaluations)"
    )
    ax.set_xlabel("Objective Evaluations")
    ax.set_ylabel("Mean Best-So-Far Tour Length")
    ax.grid(True, linestyle=":", alpha=0.6)
    ax.legend(loc="upper right", frameon=True)
    fig.tight_layout()

    out_path = base / "figures" / f"convergence_{instance}.png"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out_path, dpi=300)
    plt.close(fig)
    logger.info(f"Saved TSP convergence plot: {out_path}")
    return out_path


def plot_best_berlin52_route(
    tsp_path: str | Path = DEFAULT_BERLIN52_PATH,
    results_dir: str | Path = DEFAULT_RESULTS_DIR,
) -> Path | None:
    """
    Plot the shortest valid berlin52 tour found across both neighbourhood versions
    and all runs, including the explicit return leg and full run metadata.
    """
    base = Path(results_dir) / "part_a_tsp"
    runs_csv = base / "raw" / "runs.csv"
    solutions_json = base / "raw" / "solutions.json"

    if not runs_csv.exists():
        logger.warning("TSP runs.csv not found; skipping berlin52 route plot.")
        return None

    with runs_csv.open("r", newline="", encoding="utf-8") as f:
        berlin_rows = [r for r in csv.DictReader(f) if r["instance"] == "berlin52"]

    if not berlin_rows:
        logger.warning("No berlin52 runs found in runs.csv; skipping route plot.")
        return None

    valid_rows = [
        r for r in berlin_rows if str(r["is_valid"]).strip().lower() in {"true", "1"}
    ]
    pool = valid_rows if valid_rows else berlin_rows
    if not valid_rows:
        logger.warning(
            "No valid berlin52 tours marked; plotting lowest-length tour found."
        )

    best_row = min(pool, key=lambda r: float(r["final_best"]))

    route: list[int] | None = None
    if solutions_json.exists():
        solutions = json.loads(solutions_json.read_text(encoding="utf-8"))
        key = f"berlin52__{best_row['neighbourhood']}__seed_{best_row['seed']}"
        if key in solutions and solutions[key].get("solution"):
            route = [int(c) for c in solutions[key]["solution"]]

    if route is None:
        route = [int(c) for c in json.loads(best_row["solution"])]

    coords = load_data(str(tsp_path))

    xs = [coords[city][0] for city in route]
    ys = [coords[city][1] for city in route]

    start_city = route[0]
    end_city = route[-1]

    fig, ax = plt.subplots(figsize=(9.0, 6.5))

    ax.plot(
        xs,
        ys,
        color="#1f77b4",
        linewidth=1.6,
        zorder=2,
        label="Tour path",
    )
    ax.plot(
        [coords[end_city][0], coords[start_city][0]],
        [coords[end_city][1], coords[start_city][1]],
        color="#d62728",
        linestyle="--",
        linewidth=2.0,
        zorder=3,
        label=f"Return leg ({end_city} → {start_city})",
    )

    all_x = [coords[c][0] for c in coords if c != start_city]
    all_y = [coords[c][1] for c in coords if c != start_city]
    ax.scatter(all_x, all_y, c="#2b2b2b", s=28, zorder=4, label="Cities")

    ax.scatter(
        [coords[start_city][0]],
        [coords[start_city][1]],
        c="#ff7f0e",
        marker="*",
        s=220,
        edgecolors="black",
        linewidths=0.8,
        zorder=5,
        label=f"Start city (City {start_city})",
    )
    ax.annotate(
        f"Start: City {start_city}",
        xy=(coords[start_city][0], coords[start_city][1]),
        xytext=(0, -32),
        textcoords="offset points",
        ha="center",
        fontsize=9,
        fontweight="bold",
        bbox=dict(boxstyle="round,pad=0.25", fc="#fff3cd", ec="#ff7f0e", alpha=0.95),
        arrowprops=dict(arrowstyle="->", color="#ff7f0e", lw=1.3),
        zorder=6,
    )

    tour_len = float(best_row["final_best"])
    gap_pct = float(best_row["gap_pct"])
    neighbourhood = best_row["neighbourhood"]
    seed = best_row["seed"]

    ax.set_title(
        f"Shortest Valid berlin52 Tour Found\n"
        f"Neighbourhood: {neighbourhood} | Seed: {seed} | "
        f"Length: {tour_len:.0f} (Optimum: {TSP_OPTIMA['berlin52']}) | "
        f"Gap: {gap_pct:.2f}% | Start City: {start_city}"
    )
    ax.set_xlabel("X Coordinate")
    ax.set_ylabel("Y Coordinate")
    ax.grid(True, linestyle=":", alpha=0.5)
    ax.legend(loc="best", frameon=True)
    fig.tight_layout()

    out_path = base / "figures" / "best_route_berlin52.png"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out_path, dpi=300)
    plt.close(fig)
    logger.info(f"Saved berlin52 best route plot: {out_path}")
    return out_path


def plot_rastrigin_d10_convergence(
    results_dir: str | Path = DEFAULT_RESULTS_DIR,
) -> Path | None:
    """
    Plot evaluations vs. mean best-so-far objective across 10 runs for Rastrigin at D=10.
    Explicitly labels any axis transformation.
    """
    base = Path(results_dir) / "part_b_continuous"
    hist_path = base / "histories" / "rastrigin_D10.csv"
    if not hist_path.exists():
        logger.warning(f"Rastrigin D=10 history not found: {hist_path}")
        return None

    evals, mat = _load_history_csv(hist_path)
    mean_curve = np.nanmean(mat, axis=1)
    std_curve = np.nanstd(mat, axis=1, ddof=1) if mat.shape[1] > 1 else None
    n_runs = mat.shape[1]

    fig, ax = plt.subplots(figsize=(8.5, 5.2))
    ax.plot(
        evals,
        mean_curve,
        color="#1f77b4",
        linewidth=2.0,
        label=f"Mean best-so-far ({n_runs} runs)",
    )

    y_scale_label = "linear scale"
    positive = mean_curve[np.isfinite(mean_curve)]
    if positive.size > 0:
        min_val = float(np.min(positive))
        max_val = float(np.max(positive))
        if min_val > 0 and max_val / min_val > 20:
            ax.set_yscale("log")
            y_scale_label = "log10 scale"
        elif min_val == 0 and max_val > 20:
            ax.set_yscale("symlog", linthresh=1e-4)
            y_scale_label = "symlog scale, linthresh=1e-4"

    if std_curve is not None and y_scale_label == "linear scale":
        ax.fill_between(
            evals,
            mean_curve - std_curve,
            mean_curve + std_curve,
            color="#1f77b4",
            alpha=0.15,
            label="±1 std",
        )

    ax.set_title(
        f"Rastrigin (D = 10): Mean Best-So-Far Convergence ({n_runs} Runs, 30,000 Evals)"
    )
    ax.set_xlabel("Objective Evaluations")
    ax.set_ylabel(f"Mean Best-So-Far Objective ({y_scale_label})")
    ax.grid(True, which="both", linestyle=":", alpha=0.6)
    ax.legend(loc="upper right", frameon=True)
    fig.tight_layout()

    out_path = base / "figures" / "convergence_rastrigin_D10.png"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out_path, dpi=300)
    plt.close(fig)
    logger.info(f"Saved Rastrigin D=10 convergence plot: {out_path}")
    return out_path


def plot_d30_boxplots(
    results_dir: str | Path = DEFAULT_RESULTS_DIR,
) -> Path | None:
    """
    Create a single 4-panel figure showing boxplots of final objective values at D=30
    for Sphere, Rosenbrock, Rastrigin, and Ackley.
    """
    base = Path(results_dir) / "part_b_continuous"
    runs_csv = base / "raw" / "runs.csv"
    if not runs_csv.exists():
        logger.warning("Continuous runs.csv not found; skipping D=30 boxplots.")
        return None

    with runs_csv.open("r", newline="", encoding="utf-8") as f:
        d30_rows = [r for r in csv.DictReader(f) if int(r["dimension"]) == 30]

    if not d30_rows:
        logger.warning("No D=30 continuous runs found in runs.csv; skipping boxplots.")
        return None

    functions = ["sphere", "rosenbrock", "rastrigin", "ackley"]
    values_by_func: dict[str, list[float]] = {fn: [] for fn in functions}
    for row in d30_rows:
        fn = row["function"].lower()
        if fn in values_by_func:
            values_by_func[fn].append(float(row["final_best"]))

    fig, axes = plt.subplots(2, 2, figsize=(10.5, 8.0))
    rng = np.random.default_rng(42)

    for ax, fn in zip(axes.flat, functions):
        vals = values_by_func[fn]
        if not vals:
            ax.set_title(f"{fn.capitalize()} (D = 30) — No Data")
            ax.axis("off")
            continue

        ax.boxplot(
            vals,
            widths=0.45,
            showfliers=False,
            patch_artist=True,
            boxprops=dict(facecolor="#cfe2f3", color="#1f77b4", linewidth=1.3),
            medianprops=dict(color="#d62728", linewidth=1.8),
            whiskerprops=dict(color="#1f77b4"),
            capprops=dict(color="#1f77b4"),
        )
        jitter = rng.normal(1.0, 0.04, size=len(vals))
        ax.scatter(jitter, vals, color="#1f77b4", alpha=0.7, s=22, zorder=3)

        scale_label = "linear"
        min_v, max_v = min(vals), max(vals)
        if min_v > 0 and max_v / min_v > 100:
            ax.set_yscale("log")
            scale_label = "log10"

        ax.set_title(f"{fn.capitalize()} (D = 30)")
        ax.set_xticks([1])
        ax.set_xticklabels([f"{fn.capitalize()} (n={len(vals)})"])
        ax.set_ylabel(f"Final Objective Value ({scale_label} scale)")
        ax.grid(True, axis="y", linestyle=":", alpha=0.6)

    fig.suptitle(
        "Bees Algorithm — Final Objective Values at D = 30 (10 Independent Runs, 30,000 Evaluations)",
        fontsize=13,
        fontweight="bold",
        y=0.98,
    )
    fig.text(
        0.5,
        0.01,
        "Figure: Boxplots of final best objective values across 10 independent seeds at D = 30 (30,000 evaluations per run).",
        ha="center",
        fontsize=9,
        style="italic",
    )
    fig.tight_layout(rect=(0.0, 0.03, 1.0, 0.95))

    out_path = base / "figures" / "boxplots_D30.png"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out_path, dpi=300)
    plt.close(fig)
    logger.info(f"Saved D=30 four-panel boxplot: {out_path}")
    return out_path


def generate_all_plots_bees(
    results_dir: str | Path = DEFAULT_RESULTS_DIR,
    berlin52_path: str | Path = DEFAULT_BERLIN52_PATH,
) -> dict[str, Path | None]:
    return {
        "convergence_berlin52": plot_tsp_convergence(
            "berlin52", optimum=TSP_OPTIMA["berlin52"], results_dir=results_dir
        ),
        "convergence_ch150": plot_tsp_convergence(
            "ch150", optimum=TSP_OPTIMA["ch150"], results_dir=results_dir
        ),
        "best_route_berlin52": plot_best_berlin52_route(
            tsp_path=berlin52_path, results_dir=results_dir
        ),
        "convergence_rastrigin_D10": plot_rastrigin_d10_convergence(
            results_dir=results_dir
        ),
        "boxplots_D30": plot_d30_boxplots(results_dir=results_dir),
    }


if __name__ == "__main__":
    generate_all_plots_bees()
